// ICSE 10 Mathematics ch10 Geometric Progression — practice bank with independent re-solve checks.
// Keys and option values are typed as literals; each check recomputes them with gp.mjs (exact BigInt rationals):
// every term by a r^{n-1} AND by listing the sequence, every sum by both closed forms AND by adding the listed
// terms, every "which term"/"how many terms" answer by walking the list, and a, r from two terms by exact
// rational roots (all roots found). Every typed working line in a solution or model answer is parsed and checked
// exactly by steps() in gp.mjs.
import { Q, mk, r } from './lib.mjs';
import { Q as Rat, q, gp, ratioOf, fromTwoTerms, termLine, sumLine, seqTex, addTex, steps, checkLine, gctx, uctx, nctx, ARITH } from './gp.mjs';

const J = (lines) => lines.join('\n\n');
const W = (ctx, lines) => steps(ctx, lines);
const num = (x) => Rat.of(x).num();
const M = (t) => `$${t}$`;
/** True when the typed formula in n equals T_n (or S_n) of g for n = 1…7. */
const isTn = (tex, g, name = 'T') => checkLine(`${name}_{n} = ${tex}`, nctx(g)).length === 0;

// =============================================================== MCQ
const g01 = gp(4, 5);
const w01 = W(gctx(g01), [r`\dfrac{20}{4} = \dfrac{100}{20} = 5`]);
Q('m01', mk.mcq({ stem: r`In a geometric progression, the common ratio is found by`, opts: ['dividing any term by the term just before it', 'subtracting any term from the term just after it', 'dividing the first term by the last term', 'multiplying any two neighbouring terms'], key: 'a', sol: `Each term is the term before it multiplied by $r$, so $r$ is any term divided by the one before it. For $${seqTex(g01.list(3))}$: ${w01.md[0]}. Option (b) gives the common difference of an arithmetic progression.`, d: 1, c: 'recall', t: [1] }), (C) => { w01.verify(C); C.assert(ratioOf(g01.list(5)).eq(5), 'ratio 5'); C.key('a'); });

const lists02 = [[4, 12, 36, 108], [4, 8, 12, 16], [4, 8, 16, 24], [4, 6, 9, 12]];
const w02 = W(ARITH, [r`\dfrac{12}{4} = \dfrac{36}{12} = \dfrac{108}{36} = 3`, r`\dfrac{24}{16} = 1.5`, r`\dfrac{12}{9} = \dfrac{4}{3}`]);
Q('m02', mk.mcq({ stem: r`Only one of these lists is multiplied by the same number at every step. Which list is a geometric progression?`, opts: lists02.map((l) => M(seqTex(l, { dots: false }))), key: 'a', sol: `In the first list every ratio is the same: ${w02.md[0]}. In (c), ${w02.md[1]} breaks the pattern of doubling; in (d), ${w02.md[2]}, not $1.5$; (b) adds $4$ each time.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { w02.verify(C); C.which(lists02.map((l) => (ratioOf(l) ? 'gp' : 'no')), 'gp'); });

const l03 = [q(2, 3), q(-1, 2), q(3, 8)];
const w03 = W(uctx('r', [q(-3, 4)]), [r`r = -\dfrac{1}{2} \div \dfrac{2}{3} = -\dfrac{3}{4}`, r`\dfrac{3}{8} \div \left(-\dfrac{1}{2}\right) = -\dfrac{3}{4}`, r`-\dfrac{1}{2} - \dfrac{2}{3} = -\dfrac{7}{6}`]);
Q('m03', mk.mcq({ stem: `What is the common ratio of the geometric progression $${seqTex(l03)}$?`, opts: [r`$-\dfrac{3}{4}$`, r`$\dfrac{3}{4}$`, r`$-\dfrac{4}{3}$`, r`$-\dfrac{7}{6}$`], key: 'a', sol: `${w03.md[0]}, and ${w03.md[1]} as well. Option (c) divides the wrong way round, (b) loses the sign, and (d) is the difference ${w03.md[2]}.`, d: 2, c: 'understanding', t: [1] }), (C) => { w03.verify(C); C.which([-3 / 4, 3 / 4, -4 / 3, -7 / 6], num(ratioOf(l03))); });

const g04 = gp(3, -2);
const w04 = W(gctx(g04), [termLine(g04, 10)]);
Q('m04', mk.mcq({ stem: `Find the $10$th term of the geometric progression $${seqTex(g04.list(3))}$.`, opts: ['$-1536$', '$1536$', '$3072$', '$768$'], key: 'a', sol: `$a = 3$ and $r = -2$: ${w04.md[0]}. Option (b) drops the minus sign of $(-2)^{9}$; (c) uses the power $10$ and (d) the power $8$.`, d: 2, c: 'understanding', t: [1], time: 75 }), (C) => { w04.verify(C); C.assert(g04.term(11).eq(3072) && g04.term(9).eq(768), 'distractors T11, T9'); C.which([-1536, 1536, 3072, 768], num(g04.term(10))); });

const g05 = gp(7, 2);
const w05 = W(uctx('n', [10]), [r`7 \times 2^{n - 1} = 3584`, r`2^{n - 1} = 512 = 2^{9}`, r`n - 1 = 9`, r`n = 10`]);
Q('m05', mk.mcq({ stem: `In the geometric progression $${seqTex(g05.list(3))}$, the number $3584$ appears as which term?`, opts: ['$10$th', '$9$th', '$512$th', '$11$th'], key: 'a', sol: `$T_{n} = 7 \\times 2^{n - 1}$: ${w05.md[0]}, so ${w05.md[1]}, ${w05.md[2]} and ${w05.md[3]}. Option (b) forgets that the power is $n - 1$; (c) is $2^{n - 1}$ itself.`, d: 2, c: 'application', t: [1], time: 90 }), (C) => { w05.verify(C); C.which([10, 9, 512, 11], g05.whichTerm(3584)); });

const g06 = gp(5, 3);
const o06 = [r`5 \times 3^{n - 1}`, r`5 \times 3^{n}`, r`15^{n - 1}`, r`3 \times 5^{n - 1}`];
const w06 = W(gctx(g06), [r`r = \dfrac{15}{5} = 3`, r`T_{3} = 5 \times 3^{2} = 45`]);
const w06n = W(nctx(g06), [r`T_{n} = ar^{n - 1} = 5 \times 3^{n - 1}`]);
Q('m06', mk.mcq({ stem: `Which expression gives the $n$th term of the geometric progression $${seqTex(g06.list(3))}$?`, opts: o06.map(M), key: 'a', sol: `$a = 5$ and ${w06.md[0]}, so ${w06n.md[0]}. Check: ${w06.md[1]}. Option (b) would make the first term $15$.`, d: 2, c: 'understanding', t: [1] }), (C) => { w06.verify(C); w06n.verify(C); C.which(o06.map((o) => (isTn(o, g06) ? 'yes' : 'no')), 'yes'); });

const s07 = fromTwoTerms(2, 18, 5, -486);
const w07 = W(gctx(s07[0]), [r`\dfrac{T_{5}}{T_{2}} = \dfrac{ar^{4}}{ar} = r^{3}`, r`r^{3} = \dfrac{-486}{18} = -27`, r`r = -3`]);
Q('m07', mk.mcq({ stem: r`The second term of a geometric progression is $18$ and its fifth term is $-486$. What is its common ratio?`, opts: ['$-3$', '$3$', '$-27$', r`$-\dfrac{1}{3}$`], key: 'a', sol: `${w07.md[0]}, so ${w07.md[1]} and ${w07.md[2]} (a negative number has a negative cube root). Option (c) stops at $r^{3}$; (b) loses the sign.`, d: 3, c: 'application', t: [1], time: 90 }), (C) => { w07.verify(C); C.assert(s07.length === 1 && s07[0].a.eq(-6), 'one GP, a = -6'); C.which([-3, 3, -27, -1 / 3], num(s07[0].r)); });

const w08 = W(uctx('x', [10]), [r`x^{2} = 4 \times 25 = 100`, r`x = 10`]);
const w08b = W(ARITH, [r`\dfrac{4 + 25}{2} = 14.5`]);
Q('m08', mk.mcq({ stem: r`The numbers $4$, $x$ and $25$ are consecutive terms of a geometric progression whose terms are all positive. Find $x$.`, opts: ['$10$', '$14.5$', '$100$', '$21$'], key: 'a', sol: `For consecutive terms, $\\dfrac{x}{4} = \\dfrac{25}{x}$, so ${w08.md[0]} and, as $x > 0$, ${w08.md[1]}. Option (b) is the middle term of an arithmetic progression, ${w08b.md[0]}.`, d: 2, c: 'application', t: [1] }), (C) => { w08.verify(C); w08b.verify(C); C.assert(ratioOf([4, 10, 25]).eq(q(5, 2)), '4, 10, 25 is a GP'); C.which([10, 14.5, 100, 21], [10, 14.5, 100, 21].find((x) => x > 0 && ratioOf([4, Rat.of(String(x)), 25]))); });

const g09 = gp(2, 2), N09 = g09.whichTerm(1024);
const w09 = W(ARITH, [r`1024 \times \left(\dfrac{1}{2}\right)^{2} = 256`]);
Q('m09', mk.mcq({ stem: r`The geometric progression $2, 4, 8, \ldots, 1024$ ends at $1024$. What is its third term counted from the end?`, opts: ['$256$', '$8$', '$512$', '$128$'], key: 'a', sol: `Counting back from the last term, divide by $r = 2$ at each step: ${w09.md[0]}. Option (b) is the third term from the beginning; (c) is the second term from the end and (d) the fourth.`, d: 2, c: 'understanding', t: [1] }), (C) => { w09.verify(C); C.assert(N09 === 10 && g09.term(3).eq(8) && g09.fromEnd(10, 2).eq(512) && g09.fromEnd(10, 4).eq(128), 'distractors'); C.which([256, 8, 512, 128], num(g09.fromEnd(N09, 3))); });

const g10 = gp(1, 3);
const w10 = W(gctx(g10), [sumLine(g10, 5), r`1 + 3 + 9 + 27 + 81 = 121`]);
Q('m10', mk.mcq({ stem: `What total do you get by adding up five terms, starting from the first, of $${seqTex(g10.list(3))}$, a geometric progression with ratio $3$?`, opts: ['$121$', '$81$', '$364$', '$40$'], key: 'a', sol: `$a = 1$, $r = 3$: ${w10.md[0]}. Check: ${w10.md[1]}. Option (b) is the fifth term; (c) is the sum of six terms and (d) of four.`, d: 1, c: 'understanding', t: [2], time: 60 }), (C) => { w10.verify(C); C.assert(g10.term(5).eq(81) && g10.sum(6).eq(364) && g10.sum(4).eq(40), 'distractors'); C.which([121, 81, 364, 40], num(g10.sum(5))); });

const o11 = [r`\dfrac{a\left(1 - r^{n}\right)}{1 - r}`, r`\dfrac{a\left(1 - r^{n}\right)}{1 + r}`, r`\dfrac{a\left(1 - r^{n - 1}\right)}{1 - r}`, r`ar^{n - 1}`];
const g11a = gp(6, q(1, 2)), g11b = gp(5, -2);
const w11 = W(nctx(g11a), [r`S_{n} - rS_{n} = a - ar^{n}`]);
Q('m11', mk.mcq({ stem: r`A geometric progression has first term $a$ and common ratio $r$, where $r < 1$. Which formula gives the sum of its first $n$ terms?`, opts: o11.map(M), key: 'a', sol: `Write $S_{n} = a + ar + \\cdots + ar^{n - 1}$, multiply by $r$ and subtract: ${w11.md[0]}, so $S_{n} = ${o11[0]}$. Option (d) is the $n$th term, not the sum.`, d: 2, c: 'understanding', t: [2] }), (C) => { w11.verify(C); W(nctx(g11b), [r`S_{n} - rS_{n} = a - ar^{n}`]).verify(C); C.which(o11.map((o) => (isTn(o, g11a, 'S') && isTn(o, g11b, 'S') ? 'yes' : 'no')), 'yes'); });

const g12 = gp(1, q(1, 2));
const w12 = W(gctx(g12), [sumLine(g12, 8)]);
Q('m12', mk.mcq({ stem: `What is the sum of the first $8$ terms of $${seqTex(g12.list(3))}$, a geometric progression with ratio one half?`, opts: [r`$\dfrac{255}{128}$`, '$2$', r`$\dfrac{127}{64}$`, r`$\dfrac{511}{256}$`], key: 'a', sol: `Here $r < 1$: ${w12.md[0]}. Option (c) is the sum of $7$ terms and (d) of $9$ terms; the sums get closer to $2$ but never reach it.`, d: 2, c: 'understanding', t: [2], time: 75 }), (C) => { w12.verify(C); C.assert(g12.sum(7).eq(q(127, 64)) && g12.sum(9).eq(q(511, 256)), 'distractors'); C.which([255 / 128, 2, 127 / 64, 511 / 256], num(g12.sum(8))); });

const g13 = gp(3, 2);
const w13 = W({ sols: [{ n: q(7) }], fns: { S: (k) => g13.sum(k) } }, [r`S_{n} = \dfrac{3\left(2^{n} - 1\right)}{2 - 1} = 381`, r`2^{n} - 1 = 127`, r`2^{n} = 128 = 2^{7}`, r`n = 7`]);
const w13b = W(gctx(g13), [r`S_{6} = 189`, r`S_{8} = 765`]);
Q('m13', mk.mcq({ stem: `How many terms of the geometric progression $${seqTex(g13.list(3))}$ must be added to give $381$?`, opts: ['$7$', '$6$', '$8$', '$127$'], key: 'a', sol: `${w13.md[0]}, so ${w13.md[1]}, ${w13.md[2]} and ${w13.md[3]}. Options (b) and (c) give ${w13b.md[0]} and ${w13b.md[1]}; (d) is the value of $2^{n} - 1$.`, d: 2, c: 'application', t: [2], time: 90 }), (C) => { w13.verify(C); w13b.verify(C); C.which([7, 6, 8, 127], g13.termsForSum(381)); });

const g14 = gp(7, 1);
const w14 = W(gctx(g14), [r`S_{12} = 12 \times 7 = 84`]);
Q('m14', mk.mcq({ stem: r`Every term of the geometric progression $7, 7, 7, \ldots$ equals $7$. What is the sum of its first $12$ terms?`, opts: ['$84$', '$0$', '$7^{12}$', '$12$'], key: 'a', sol: `Here $r = 1$, and the formula $\\dfrac{a\\left(r^{n} - 1\\right)}{r - 1}$ cannot be used: it would divide by $0$. Add directly: ${w14.md[0]}.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => { w14.verify(C); C.which([84, 0, 7 ** 12, 12], num(g14.sum(12))); });

const g15 = gp(50000, '0.8');
const w15 = W(uctx('r', ['0.8']), [r`r = 1 - \dfrac{20}{100} = 0.8`]);
const w15b = W(ARITH, [r`50000 \times 0.8^{2} = 32000`]);
Q('m15', mk.mcq({ stem: r`An imagined printing press buys a machine for ₹50,000. Its value falls by $20\%$ of its value at the start of each year. What is the machine worth after $2$ years?`, opts: ['₹32,000', '₹30,000', '₹40,000', '₹36,000'], key: 'a', sol: `The values form a geometric progression with ${w15.md[0]}, so after $2$ years the value in rupees is ${w15b.md[0]}. Option (b) takes $20\\%$ of the original price twice, and (c) is the value after one year.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { w15.verify(C); w15b.verify(C); C.assert(g15.term(2).eq(40000), 'value after one year'); C.which([32000, 30000, 40000, 36000], num(g15.term(3))); });

const g16 = gp(500, 2);
const w16 = W(gctx(g16), [termLine(g16, 7)]);
Q('m16', mk.mcq({ stem: r`In an imagined laboratory, a culture of $500$ cells doubles every hour. How many cells are there after $6$ hours?`, opts: ['$32000$', '$16000$', '$6000$', '$64000$'], key: 'a', sol: `The counts at $0, 1, 2, \\ldots$ hours form a geometric progression with $a = 500$ and $r = 2$, and after $6$ hours we need the $7$th term: ${w16.md[0]}. Option (b) uses $2^{5}$, (d) uses $2^{7}$, and (c) is $500 \\times 2 \\times 6$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { w16.verify(C); C.assert(g16.term(6).eq(16000) && g16.term(8).eq(64000), 'off-by-one distractors'); C.which([32000, 16000, 6000, 64000], num(g16.term(7))); });

const g17 = gp(3, 2), S17 = (n) => q(3).mul(q(2).pow(n).sub(1));
const w17 = W({ sols: [{}], fns: { S: S17, T: (k) => g17.term(k) } }, [r`T_{5} = S_{5} - S_{4} = 93 - 45 = 48`]);
Q('m17', mk.mcq({ stem: r`The sum of the first $n$ terms of a geometric progression is $S_{n} = 3\left(2^{n} - 1\right)$. What is its fifth term?`, opts: ['$48$', '$93$', '$45$', '$96$'], key: 'a', sol: `The fifth term is what the fifth term adds to the sum: ${w17.md[0]}. Option (b) is $S_{5}$ and (c) is $S_{4}$; (d) is the sixth term.`, d: 3, c: 'analysis', t: [2], time: 90 }), (C) => { w17.verify(C); C.assert([1, 2, 3, 4, 5, 6, 7, 8].every((n) => S17(n).eq(g17.sum(n))), 'S_n = 3(2^n - 1) is the GP 3, 6, 12'); C.assert(g17.term(6).eq(96), 'T6'); C.which([48, 93, 45, 96], num(S17(5).sub(S17(4)))); });

const base18 = [q(1), q(2), q(4)];
const tr18 = [(x) => x.add(1), (x) => x.mul(3), (x) => x.pow(2), (x) => x.inv()];
const w18 = W(ARITH, [r`\dfrac{3}{2} \ne \dfrac{5}{3}`]);
Q('m18', mk.mcq({ stem: r`If $a$, $b$ and $c$ are consecutive terms of a geometric progression of positive numbers, which of these lists need **not** be a geometric progression?`, opts: [r`$a + 1,\ b + 1,\ c + 1$`, r`$3a,\ 3b,\ 3c$`, r`$a^{2},\ b^{2},\ c^{2}$`, r`$\dfrac{1}{a},\ \dfrac{1}{b},\ \dfrac{1}{c}$`], key: 'a', sol: `Try $1, 2, 4$ (ratio $2$). Adding $1$ gives $2, 3, 5$, and ${w18.md[0]}. Multiplying by $3$, squaring and taking reciprocals give the ratios $2$, $4$ and $\\dfrac{1}{2}$: a common ratio survives each of them.`, d: 3, c: 'analysis', t: [1], time: 90 }), (C) => { w18.verify(C); const rs = tr18.map((f) => ratioOf(base18.map(f))); C.assert(rs[1].eq(2) && rs[2].eq(4) && rs[3].eq(q(1, 2)), 'ratios 2, 4, 1/2'); C.which(rs.map((x) => (x ? 'gp' : 'not')), 'not'); });

// =============================================================== assertion-reason (keys a b d c a d)
const gar1 = gp(q(1, 3), 3);
const war1 = W(gctx(gar1), [termLine(gar1, 6)]);
Q('ar1', mk.ar({ a: `The $6$th term of the geometric progression $${seqTex(gar1.list(3))}$ is $81$.`, r: r`The $n$th term of a geometric progression with first term $a$ and common ratio $r$ is $ar^{n - 1}$.`, key: 'a', sol: `${war1.md[0]}, so A is true, and it is found exactly by the rule in R.`, d: 2, c: 'understanding', t: [1] }), (C) => { war1.verify(C); C.assert(gar1.term(6).eq(81), 'T6 = 81'); C.key('a'); });
Q('ar2', mk.ar({ a: r`The list $5, 5, 5, 5, \ldots$ is a geometric progression.`, r: r`No term of a geometric progression can be zero.`, key: 'b', sol: r`Each term divided by the one before is $\dfrac{5}{5} = 1$, a constant, so A is true (common ratio $1$). R is also true, since a zero term would leave the next ratio undefined; but A holds because the ratio is constant, not because the terms are non-zero.`, d: 3, c: 'analysis', t: [1] }), (C) => { W(ARITH, [r`\dfrac{5}{5} = 1`]).verify(C); C.assert(ratioOf([5, 5, 5, 5]).eq(1) && ratioOf([5, 0, 0]) === null, 'ratio 1; zero terms rejected'); C.key('b'); });
const gar3 = gp(2, 3);
const war3 = W(gctx(gar3), [sumLine(gar3, 4)]);
Q('ar3', mk.ar({ a: `The sum of the first $4$ terms of the geometric progression $${seqTex(gar3.list(3))}$ is $54$.`, r: r`For a geometric progression with $r > 1$, $S_{n} = \dfrac{a\left(r^{n} - 1\right)}{r - 1}$.`, key: 'd', sol: `${war3.md[0]}, so A is false: $54$ is the fourth term, not the sum. R is the sum formula, which is true.`, d: 2, c: 'application', t: [2] }), (C) => { war3.verify(C); C.assert(gar3.term(4).eq(54) && !gar3.sum(4).eq(54), 'A false'); C.key('d'); });
const gar4 = gp(81, q(1, 3));
const war4 = W(gctx(gar4), [termLine(gar4, 6)]);
Q('ar4', mk.ar({ a: `In the geometric progression $${seqTex(gar4.list(3))}$, the $6$th term is $\\dfrac{1}{3}$.`, r: r`The terms of a geometric progression decrease only when its common ratio is negative.`, key: 'c', sol: `${war4.md[0]}, so A is true. R is false: here $r = \\dfrac{1}{3}$ is positive and the terms still decrease, because each is multiplied by a number less than $1$.`, d: 2, c: 'understanding', t: [1] }), (C) => { war4.verify(C); C.assert(gar4.term(6).eq(q(1, 3)) && gar4.list(6).every((x, i, L) => i === 0 || x.lt(L[i - 1])), 'A true; positive ratio, decreasing'); C.key('c'); });
const war5 = W(uctx('x', [9]), [r`x^{2} = 3 \times 27 = 81`, r`x = 9`]);
Q('ar5', mk.ar({ a: r`If $3$, $x$ and $27$ are consecutive terms of a geometric progression with positive terms, then $x = 9$.`, r: r`If $a$, $b$ and $c$ are consecutive terms of a geometric progression, then $b^{2} = ac$.`, key: 'a', sol: `${war5.md[0]}, and $x > 0$ gives ${war5.md[1]}, so A is true. R holds because $\\dfrac{b}{a} = \\dfrac{c}{b}$, and it is exactly the rule used to get A.`, d: 2, c: 'application', t: [1] }), (C) => { war5.verify(C); C.assert(ratioOf([3, 9, 27]).eq(3), '3, 9, 27'); C.key('a'); });
const war6 = W(ARITH, [r`20000 \times 1.1 = 22000`, r`22000 \times 1.1 = 24200`, r`22000 - 20000 = 2000`, r`24200 - 22000 = 2200`]);
Q('ar6', mk.ar({ a: r`The population of an imagined town grows by $10\%$ every year, so its populations at the end of successive years form an arithmetic progression.`, r: r`Growth by a fixed percentage multiplies a quantity by the same factor every year.`, key: 'd', sol: `Start from, say, $20000$: ${war6.md[0]} and ${war6.md[1]}. The increases ${war6.md[2]} and ${war6.md[3]} differ, so the populations do not form an arithmetic progression; they form a geometric progression with ratio $1.1$. A is false and R is true.`, d: 2, c: 'understanding', t: [3] }), (C) => { war6.verify(C); C.assert(ratioOf(gp(20000, '1.1').list(4)).eq(Rat.of('1.1')), 'ratio 1.1'); C.key('d'); });

// =============================================================== true-false
const wtf1 = W(ARITH, [r`\dfrac{4}{1} = 4`, r`\dfrac{9}{4} = 2.25`]);
Q('tf1', mk.tf({ stem: r`The list of square numbers $1, 4, 9, 16$ is a geometric progression.`, key: 'f', sol: `${wtf1.md[0]} but ${wtf1.md[1]}: the ratios differ, so the list is not a geometric progression.`, d: 1, c: 'understanding', t: [1] }), (C) => { wtf1.verify(C); C.assert(ratioOf([1, 4, 9, 16]) === null, 'not a GP'); C.key('f'); });
const gtf2 = gp(3, -2);
Q('tf2', mk.tf({ stem: r`If the common ratio of a geometric progression is negative, its terms are alternately positive and negative.`, key: 't', sol: `Each term is the term before it multiplied by a negative number, so the sign changes at every step; for example $${seqTex(gtf2.list(4), { dots: false })}$ with $r = -2$.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert([gtf2, gp(-5, q(-1, 2)), gp(q(2, 7), -3)].every((g) => g.list(8).every((x, i, L) => i === 0 || x.sign() === -L[i - 1].sign())), 'signs alternate'); C.key('t'); });
const gtf3 = gp(64, q(1, 2));
const wtf3 = W(gctx(gtf3), [termLine(gtf3, 7)]);
Q('tf3', mk.tf({ stem: `The $7$th term of the geometric progression $${seqTex(gtf3.list(3))}$ is $1$.`, key: 't', sol: `$a = 64$ and $r = \\dfrac{1}{2}$: ${wtf3.md[0]}.`, d: 1, c: 'understanding', t: [1] }), (C) => { wtf3.verify(C); C.assert(gtf3.term(7).eq(1), 'T7 = 1'); C.key('t'); });
const gtf4 = gp(1, 2);
