const sols303 = [{ a: q(7), r: q(7) }, { a: q(7), r: q(1, 7) }];
const ws303 = W({ sols: sols303, fns: {} }, [r`\dfrac{a}{r} \times a \times ar = a^{3} = 343`, r`a = 7`, r`\dfrac{7}{r} + 7 + 7r = 57`, r`\dfrac{7}{r} + 7r = 50`, r`7r^{2} - 50r + 7 = 0`, r`(7r - 1)(r - 7) = 0`, r`r = 7 \text{ or } r = \dfrac{1}{7}`]);
