Q('s303', mk.short({ marks: 3, stem: r`Three numbers in geometric progression have a product of $343$ and a sum of $57$. Taking them as $\dfrac{a}{r}$, $a$ and $ar$, find the numbers.`, model: J([`Product: ${ws303.md[0]}, so ${ws303.md[1]}.`, `Sum: ${ws303.md[2]}, so ${ws303.md[3]}.`, `Multiplying by $r$: ${ws303.md[4]}, that is ${ws303.md[5]}, so ${ws303.md[6]}.`, `Either value gives the same three numbers, $1, 7, 49$ (in one order or the other). Check: ${ws303b.md[0]} and ${ws303b.md[1]}.`]), sol: 'With the terms written as a/r, a, ar the ratio cancels in the product, which gives a at once; the sum then gives a quadratic in r.', scheme: [['a = 7 from the product', 1], ['7r² − 50r + 7 = 0', 1], ['Numbers 1, 7, 49', 1]], d: 3, c: 'analysis', t: [1], time: 240 }), (C) => { ws303.verify(C); ws303b.verify(C); for (const s of sols303) { const g = gp(s.a.div(s.r), s.r), L = g.list(3); C.assert(L.reduce((x, y) => x.mul(y)).eq(343) && g.sum(3).eq(57), `r = ${s.r}`); } C.model([7, 343, 57, 49]); });
const gs304 = gp(90000, '0.9');
