const ws402 = W({ sols: sols402, fns: {} }, [r`3 + 3r + 3r^{2} = 63`, r`r^{2} + r - 20 = 0`, r`(r + 5)(r - 4) = 0`, r`r = 4 \text{ or } r = -5`]);
