Q('s402', mk.short({ marks: 4, stem: r`The first term of a geometric progression is $3$ and the sum of its first three terms is $63$. Find the possible values of the common ratio, and write the first three terms in each case.`, model: J([`${ws402.md[0]}, so ${ws402.md[1]}.`, `${ws402.md[2]}, so ${ws402.md[3]}.`, `For $r = 4$: $3, 12, 48$, and ${ws402b.md[0]}.`, `For $r = -5$: $3, -15, 75$, and ${ws402b.md[1]}.`]), sol: 'Write the three terms as a, ar and ar² with a = 3, equate their sum to the total and solve the quadratic in r; both roots are valid.', scheme: [['3 + 3r + 3r² = 63', 1], ['r² + r − 20 = 0', 1], ['r = 4 or −5', 1], ['Both sets of terms', 1]], d: 3, c: 'analysis', t: [2], time: 300 }), (C) => { ws402.verify(C); ws402b.verify(C); C.assert(sols402.every((s) => gp(3, s.r).sum(3).eq(63)), 'both ratios give 63'); C.model([4, 5, 48, 15, 75]); });
const gs403 = gp(64000, '1.05');
const ws403 = W(ARITH, [r`r = 1 + \dfrac{5}{100} = 1.05`.replace('r = ', ''), r`64000 \times 1.05^{2} = 70560`, r`64000 \times 1.05^{3} = 74088`, r`74088 - 70560 = 3528`]);
Q('s403', mk.short({ marks: 4, stem: r`The population of an imagined town, Navgaon, is $64000$ now and grows by $5\%$ of the current population every year. Find its population after $3$ years, and the increase during the third year.`, model: J([`The populations at the end of successive years form a geometric progression with common ratio ${ws403.md[0]}.`, `After $2$ years: ${ws403.md[1]}.`, `After $3$ years: ${ws403.md[2]}.`, `Increase during the third year: ${ws403.md[3]}.`]), sol: 'Growth of five percent a year multiplies the population by 1.05 each year; the increase in a year is the difference of two consecutive terms.', scheme: [['Ratio 1.05', 1], ['After 2 years 70560', 1], ['After 3 years 74088', 1], ['Increase 3528', 1]], d: 3, c: 'application', t: [3], time: 300 }), (C) => { ws403.verify(C); C.assert(gs403.term(3).eq(70560) && gs403.term(4).eq(74088), 'terms'); C.model([1.05, 70560, 74088, 3528]); });
const gs404 = gp(3, 2), N404 = gs404.whichTerm(3072);
