Q('s404', mk.short({ marks: 4, stem: r`The geometric progression $3, 6, 12, \ldots, 3072$ is finite. Find the number of terms and the fourth term from the end.`, model: J([`$a = 3$, $r = 2$ and the last term is $T_{n} = 3072$: ${ws404.md[0]}, so ${ws404.md[1]} and ${ws404.md[2]}. There are $11$ terms.`, `Counting from the end, each step back divides by $2$, so the fourth term from the end is ${ws404b.md[0]}.`, `Check: it is the $8$th term from the start, ${ws404b.md[1]}.`]), sol: 'Find n from the last term; then count back from the last term using the reciprocal of the ratio (or use the term in place n − 3).', scheme: [['3 × 2ⁿ⁻¹ = 3072', 1], ['n = 11', 1], ['Ratio 1/2 from the end', 1], ['384', 1]], d: 3, c: 'application', t: [1], time: 300 }), (C) => { ws404.verify(C); ws404b.verify(C); C.assert(N404 === 11 && gs404.fromEnd(11, 4).eq(384), 'fourth from end'); C.model([11, 384]); });
const gs405 = gp('0.6', '0.1');
