Q('s405', mk.short({ marks: 4, stem: `Add the first five terms of the geometric progression $${seqTex(gs405.list(3), { dec: true })}$ using the sum formula, and give the total as a decimal.`, model: J([`$a = 0.6$ and ${ws405.md[0]}, which is less than $1$.`, `${ws405.md[1]}.`, `Check: ${ws405.md[2]}.`]), sol: 'Find the ratio, use the sum formula for a ratio below 1, and check by adding the five decimals.', scheme: [['a = 0.6, r = 0.1', 1], ['Formula substituted', 1], ['0.66666', 1], ['Check by adding', 1]], d: 3, c: 'application', t: [2], time: 300 }), (C) => { ws405.verify(C); C.assert(gs405.sum(5).eq(Rat.of('0.66666')), 'S5'); C.model([0.1, 0.99999, 0.66666]); });
