Q('s406', mk.short({ marks: 4, stem: r`Show that the $3$rd, $6$th and $9$th terms of any geometric progression themselves form a geometric progression. Check this for the progression $2, 4, 8, \ldots$`, model: J([`Let the first term be $a$ and the common ratio $r$. Then ${ws406.md[0]}, ${ws406.md[1]} and ${ws406.md[2]}.`, `${ws406.md[3]} and ${ws406.md[4]}.`, 'The two ratios are equal, so these three terms form a geometric progression with common ratio $r^{3}$.', `For $2, 4, 8, \\ldots$: ${ws406b.md[0]}, ${ws406b.md[1]}, ${ws406b.md[2]}, and ${ws406b.md[3]}.`]), sol: 'Write each term as a times a power of r; the ratios of neighbouring chosen terms are both r cubed.', scheme: [['T₃, T₆, T₉ in terms of a and r', 1], ['Both ratios r³', 1], ['Conclusion', 1], ['Check with 8, 64, 512', 1]], d: 3, c: 'analysis', t: [1], time: 300 }), (C) => { ws406.verify(C); ws406b.verify(C); C.assert([gp(2, 2), gp(5, q(-1, 3)), gp(q(3, 4), 7)].every((g) => ratioOf([g.term(3), g.term(6), g.term(9)]).eq(g.r.pow(3))), 'ratio r^3'); C.model([8, 64, 512]); });

