const gl01a = gp(5, -2), gl01b = gp(q(1, 9), 3);
const wl01a = W(gctx(gl01a), [r`r = \dfrac{-10}{5} = -2`, termLine(gl01a, 9), sumLine(gl01a, 6), `${addTex(gl01a.list(6))} = -105`]);
const wl01b = W(uctx('n', [8]), [r`\dfrac{1}{9} \times 3^{n - 1} = 243`, r`3^{n - 1} = 2187 = 3^{7}`, r`n - 1 = 7`, r`n = 8`]);
Q('l01', mk.long({ marks: 10, stem: `Answer each part. Show all working.\n(a) Find the $9$th term of the geometric progression $${seqTex(gl01a.list(3))}$.\n(b) Which term of the geometric progression $${seqTex(gl01b.list(3))}$ is $243$?\n(c) Find the sum of the first $6$ terms of the progression in part (a), and check your answer by adding the terms.`, model: J([`**(a)** $a = 5$ and ${wl01a.md[0]}.`, `${wl01a.md[1]}.`, `**(b)** $a = \\dfrac{1}{9}$ and $r = 3$, so $T_{n} = \\dfrac{1}{9} \\times 3^{n - 1}$: ${wl01b.md[0]}.`, `${wl01b.md[1]}, so ${wl01b.md[2]} and ${wl01b.md[3]}: $243$ is the $8$th term.`, `**(c)** $r = -2 < 1$: ${wl01a.md[2]}.`, `Check: ${wl01a.md[3]}.`]), sol: 'Part (a) uses the general term with a negative ratio; part (b) sets the general term equal to 243 and compares powers of 3; part (c) uses the sum formula with 1 − r below.', scheme: [['(a) r = −2 and T₉ = ar⁸', 1], ['(a) T₉ = 1280', 2], ['(b) 3ⁿ⁻¹ = 2187', 2], ['(b) n = 8', 1], ['(c) formula with r = −2', 2], ['(c) S₆ = −105, checked', 2]], d: 2, c: 'application', t: [1, 2], time: 600 }), (C) => { wl01a.verify(C); wl01b.verify(C); C.assert(gl01a.term(9).eq(1280) && gl01b.whichTerm(243) === 8 && gl01a.sum(6).eq(-105), 'values'); C.model([1280, 8, 105]); });
const gl02s = fromTwoTerms(4, 40, 7, 320), gl02 = gl02s[0];
const wl02 = W(gctx(gl02), [r`r^{3} = \dfrac{T_{7}}{T_{4}} = \dfrac{320}{40} = 8`, r`r = 2`, r`a = \dfrac{T_{4}}{r^{3}} = \dfrac{40}{8} = 5`, termLine(gl02, 10), sumLine(gl02, 10), r`S_{10} = \dfrac{rT_{10} - a}{r - 1} = \dfrac{2 \times 2560 - 5}{1} = 5115`]);
Q('l02', mk.long({ marks: 10, stem: r`The fourth term of a geometric progression is $40$ and its seventh term is $320$. Show all working.
(a) Find the first term and the common ratio.
(b) Find the $10$th term.
(c) Find the sum of the first $10$ terms, and check it using $S_{n} = \dfrac{rT_{n} - a}{r - 1}$.`, model: J([`**(a)** $T_{4} = ar^{3} = 40$ and $T_{7} = ar^{6} = 320$. Dividing, ${wl02.md[0]}, so ${wl02.md[1]}.`, `Then ${wl02.md[2]}.`, `**(b)** ${wl02.md[3]}.`, `**(c)** ${wl02.md[4]}.`, `Check: ${wl02.md[5]}.`]), sol: 'Part (a) divides the two terms to isolate a power of r; parts (b) and (c) use the general term and the sum formula with r > 1.', scheme: [['(a) r³ = 8, r = 2', 2], ['(a) a = 5', 1], ['(b) T₁₀ = 5 × 2⁹', 2], ['(b) T₁₀ = 2560', 1], ['(c) S₁₀ formula', 2], ['(c) S₁₀ = 5115, checked', 2]], d: 3, c: 'application', t: [1, 2], time: 600 }), (C) => { wl02.verify(C); W(gctx(gl02), [r`T_{4} = ar^{3} = 40`, r`T_{7} = ar^{6} = 320`]).verify(C); C.assert(gl02s.length === 1 && gl02.a.eq(5) && gl02.r.eq(2), 'a = 5, r = 2'); C.model([8, 5, 2560, 5115]); });
const sols03 = [{ x: q(1) }, { x: q(-4) }];
const wl03 = W({ sols: sols03, fns: {} }, [r`(x + 1)^{2} = (2x - 1)(x + 3)`, r`x^{2} + 2x + 1 = 2x^{2} + 5x - 3`, r`x^{2} + 3x - 4 = 0`, r`(x + 4)(x - 1) = 0`, r`x = 1 \text{ or } x = -4`]);
